total, survived = 0, []
for project, mutants in (("lighthouse-memory", LIBRARY), ("backend", BACKEND)):
    for name, file, old, new in mutants:
        if (ONLY and ONLY not in name) or (PROJECT and PROJECT != project):
            continue
        total += 1
        shutil.rmtree(WORK, ignore_errors=True)
        shutil.copytree(ROOT / project, WORK, ignore=shutil.ignore_patterns(".venv", "__pycache__", ".pytest_cache", ".ruff_cache", "*.egg-info"))
        target = WORK / file
        text = target.read_text()
        if text.count(old) != 1:
            print(f"SETUP ERROR  [{project}] {name}: pattern found {text.count(old)} times", flush=True); survived.append(name); continue
        target.write_text(text.replace(old, new))
        code, out = 0, ""
        first = [f"tests/{name}.py" for name in FIRST.get(file, "").split()]
        for selection in ([first] if first else []) + [[]]:
            try:
                run = subprocess.run([sys.executable, "-m", "pytest", "-q", "-x", "-p", "no:cacheprovider", *selection], cwd=WORK, capture_output=True, text=True, timeout=90)
                code, out = run.returncode, run.stdout
            except subprocess.TimeoutExpired:
                code, out = 1, "FAILED timeout"
            if code in (4, 5):  # the selection named no test that ran: it proves nothing
                code = 0
                continue
            if code != 0:
                break
        failed = [line for line in out.splitlines() if line.startswith(("FAILED", "ERROR"))]
        if code == 0:
            survived.append(name); print(f"SURVIVED     [{project}] {name}", flush=True)
        else:
            print(f"killed       {name:48s} <- {(failed[0].split('::')[-1][:60] if failed else out.strip()[-60:])}", flush=True)
shutil.rmtree(WORK, ignore_errors=True)
print(f"\n{total - len(survived)}/{total} killed; survived: {survived}")
